"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -Command '$ref=(Get-Content -Raw .'"\\REFERENCE_BINARY.txt).Trim(); function RunCap("'$exe,$arglist,$out,$err){ $p=Start-Process -FilePath $exe -ArgumentList $arglist -NoNewWindow -RedirectStandardOutput $out -RedirectStandardError $err -Wait -PassThru; return $p.ExitCode }
$cases=@(@('"'frequency','--limit','0','--select','h1','tmp\\freq.csv'),@('frequency','--limit','0','--select','1','--no-headers','tmp\\freq.csv'),@('stats','--nulls','tmp\\statsq.csv'))
foreach("'$c in $cases){$name=($c -join '"'_') -replace '["'^A-Za-z0-9]'"','_'; "'$e1=RunCap $ref $c "tmp'"\\r4_"'$name.out" "tmp'"\\r4_"'$name.err"; $e2=RunCap '"'.\\executable.cmd' "'$c "tmp'"\\p4_"'$name.out" "tmp'"\\p4_"'$name.err"; $b1=[IO.File]::ReadAllBytes((Resolve-Path "tmp'"\\r4_"'$name.out")); $b2=[IO.File]::ReadAllBytes((Resolve-Path "tmp'"\\p4_"'$name.out")); if($e1 -eq $e2 -and [Convert]::ToBase64String($b1) -eq [Convert]::ToBase64String($b2)){"ok $($c -join '"' ')\"}else{\"FAIL "'$($c -join '"' ')\"; 'REF'; Get-Content -Raw \"tmp\\r4_"'$name.out"; '"'PY'; Get-Content -Raw \"tmp\\p4_"'$name.out"}}'
